async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let pending = "";
  let eof = false;

  async function visitLine(text) {
    if (text.endsWith("\r")) text = text.slice(0, -1);
    if (text.trim().length === 0) return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return false;
    }

    const result = await visitor({ line, value });
    accepted++;
    return result === false;
  }

  async function processText(text) {
    pending += text;
    let start = 0;

    for (;;) {
      const end = pending.indexOf("\n", start);
      if (end === -1) break;

      if (await visitLine(pending.slice(start, end))) return true;
      line++;
      start = end + 1;
    }

    pending = pending.slice(start);
    return false;
  }

  try {
    for (;;) {
      const { done, value } = await reader.read();

      if (done) {
        eof = true;
        if (await processText(decoder.decode())) {
          return { accepted, rejected, stopped: true };
        }
        if (pending.length > 0 && await visitLine(pending)) {
          return { accepted, rejected, stopped: true };
        }
        return { accepted, rejected, stopped: false };
      }

      if (await processText(decoder.decode(value, { stream: true }))) {
        return { accepted, rejected, stopped: true };
      }
    }
  } finally {
    if (!eof) await reader.cancel();
    reader.releaseLock();
  }
}
